package com.turboio.addon;
import java.net.*;import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;
final class BoundedHTTP {
 static byte[] request(String url,Map<String,String> headers,String body,int cap)throws Exception{URL u=new URL(url);if(!u.getProtocol().equals("https")||u.getUserInfo()!=null||u.getRef()!=null||u.getPort()!=-1&&u.getPort()!=443)throw new IOException("HTTPS required");HttpURLConnection c=(HttpURLConnection)u.openConnection();try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(25000);c.setUseCaches(false);for(Map.Entry<String,String> h:headers.entrySet()){if(h.getValue().contains("\r")||h.getValue().contains("\n"))throw new IOException();c.setRequestProperty(h.getKey(),h.getValue());}if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write(body.getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();if(code!=200)throw new IOException("HTTP "+code);if(c.getContentLengthLong()>cap)throw new IOException("response limit");try(InputStream in=c.getInputStream()){return read(in,cap);}}finally{c.disconnect();}}
 static byte[] read(InputStream in,int cap)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(n>cap-out.size())throw new IOException("size limit");out.write(b,0,n);}return out.toByteArray();}
}
